fn main() {
    // Fixed worker pool processing a queue — bounded by construction.
    let jobs = vec![1u64, 2, 3, 4];
    let mut handles = Vec::new();
    let chunks: Vec<Vec<u64>> = jobs.chunks(2).map(<[u64]>::to_vec).collect();
    for chunk in chunks {
        handles.push(std::thread::spawn(move || {
            chunk.iter().map(|n| n * n).sum::<u64>()
        }));
    }
    let total: u64 = handles.into_iter().map(|h| h.join().expect("join")).sum();
    println!("total {total}");
}

