fn main() {
    let items = vec![4u32, 3, 2, 1];
    let mid = items.len() / 2;
    let halves = [items[..mid].to_vec(), items[mid..].to_vec()];
    let mut handles = Vec::new();
    for half in halves {
        handles.push(std::thread::spawn(move || {
            for n in half {
                println!("{}", n * n);
            }
        }));
    }
    for h in handles {
        h.join().expect("join");
    }
}
